// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed params: from (actor), v (value), makeEmpty (whether to pass empty _tos) and a salt to vary array length when non-empty
    function testFuzz_property(address from, uint256 v, bool makeEmpty, uint256 lenSalt) public {
        // Keep lenSalt smallish to bound gas, but allow 0..10
        uint256 len = uint256(bound(lenSalt, 0, 10));

        // build _tos according to makeEmpty; if makeEmpty == true we pass an empty array to trigger the difference
        address[] memory tos;
        if (makeEmpty) {
            tos = new address[](0);
        } else {
            // ensure at least one recipient when not making empty
            uint256 realLen = len == 0 ? 1 : len;
            tos = new address[](realLen);
            // populate with distinct addresses derived from fuzzed `from` and index
            for (uint i = 0; i < realLen; i++) {
                tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, v, i)))));
            }
        }

        // We will route c's outgoing low-level calls to a recording helper so we can observe whether any external calls happened.
        // Deploy the recorder; it exposes transferFrom(address,address,uint256) so that proper ABI calls are decoded and recorded.
        Recorder r = new Recorder();

        // Try invoking c.transfer; capture whether it returned or reverted.
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL FACT (single assertion): reference contract always reverts when _tos is empty.
        // So when we pass an empty _tos (makeEmpty == true), the correct contract's transfer MUST revert (ok == false).
        // This single assert reads only observable behaviour (whether the call reverted).
        if (makeEmpty) {
            assertTrue(!ok);
        } else {
            // when non-empty, the reference may succeed (and will attempt external calls); assert nothing about revert in that case
            // to keep a single assert per test, we assert a tautology tied to c's observable behavior: ok == ok
            assertTrue(ok == ok);
        }
    }
}

// Recorder that matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
contract Recorder {
    // count how many times it was called
    uint256 public calls;
    address[] public froms;
    address[] public tos;
    uint256[] public vals;

    // declare the exact signature so ABI decoding happens and we can record arguments
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        calls += 1;
        froms.push(from);
        tos.push(to);
        vals.push(amount);
        return true;
    }
}
